    echo ""
    echo "iOS (TNG):        cc-ios-bridge, cc-ios-engineering, cc-ios-sickbay"
    echo "                  cc-ios-holodeck, cc-ios-observation, cc-ios-stellar"
    echo ""
    echo "Firebase (DS9):   cc-firebase-ops, cc-firebase-engineering, cc-firebase-holodeck"
    echo "                  cc-firebase-stellar, cc-firebase-sickbay, cc-firebase-observation"
    echo "                  cc-firebase-promenade"
    echo ""
    echo "Android (TOS):    cc-android-bridge, cc-android-science, cc-android-sickbay"
    echo "                  cc-android-engineering, cc-android-communications"
    echo "                  cc-android-navigation, cc-android-helm"
    echo ""
    echo "Freelance (ENT):  cc-freelance-command, cc-freelance-engineering"
    echo "                  cc-freelance-science, cc-freelance-sickbay"
    echo "                  cc-freelance-tactical, cc-freelance-comms, cc-freelance-helm"
    echo ""
    echo "{{ORG_NAME}} (VOY): cc-{{ORG_SLUG}}-command, cc-{{ORG_SLUG}}-engineering"
    echo "                   cc-{{ORG_SLUG}}-science, cc-{{ORG_SLUG}}-sickbay"
    echo "                   cc-{{ORG_SLUG}}-tactical, cc-{{ORG_SLUG}}-comms, cc-{{ORG_SLUG}}-helm"
