    echo "DNS (LD):         cc-dns-command, cc-dns-bugbay, cc-dns-testing, cc-dns-build"
    echo "                  cc-dns-refactor, cc-dns-apidesign, cc-dns-docs"
    echo ""
    echo "Academy (32nd):   cc-academy-chancellor, cc-academy-engineering"
    echo "                  cc-academy-medical, cc-academy-training"
